    import sys
    import threading

    def solve():
        t = int(sys.stdin.readline())
        results = []

        for _ in range(t):
            n = int(sys.stdin.readline())
            a = list(map(int, sys.stdin.readline().split()))

            # Check if it's possible to connect all districts without revolts
            unique_gangs = set(a)
            if len(unique_gangs) < n - 1:
                results.append("NO")
                continue

            # Create a graph where each gang is a node
            gang_to_districts = {}
            for i in range(n):
                if a[i] not in gang_to_districts:
                    gang_to_districts[a[i]] = []
                gang_to_districts[a[i]].append(i + 1)

            # Try to connect districts
            edges = []
            used_gangs = set()
            for i in range(n):
                if a[i] in used_gangs:
                    continue
                used_gangs.add(a[i])
                for j in range(i + 1, n):
                    if a[j] != a[i]:
                        edges.append((i + 1, j + 1))
                        used_gangs.add(a[j])
                        break
                else:
                    results.append("NO")
                    break
            else:
                if len(edges) == n - 1:
                    results.append("YES")
                    for x, y in edges:
                        results.append(f"{x} {y}")
                else:
                    results.append("NO")

        for result in results:
            print(result)

    threading.Thread(target=solve).start()

